import pytest

from minisheet.refs import Ref, parse_range, parse_ref, to_a1


def test_table():
    assert parse_ref("B12") == Ref(1, 11, False, False)
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)
    assert parse_range("$C3:A$1") == (Ref(0, 0, False, True), Ref(2, 2, True, False))
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"


@pytest.mark.parametrize("s", ["A0", "AAA1", "A01", "A10000", "", "A1 ", "A1\n", "1A", "A$"])
def test_bad_refs(s):
    with pytest.raises(ValueError):
        parse_ref(s)


def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


def test_range_same_and_ties():
    assert parse_range("A1:A1") == (Ref(0, 0), Ref(0, 0))
    assert parse_range("$A1:A$2") == (Ref(0, 0, True, False), Ref(0, 1, False, True))


def test_to_a1_out_of_range():
    for r in (Ref(702, 0), Ref(0, 9999), Ref(-1, 0), Ref(0, -1)):
        with pytest.raises(ValueError):
            to_a1(r)
    assert to_a1(Ref(701, 9998)) == "ZZ9999"
    assert to_a1(Ref(25, 0)) == "Z1"
    assert to_a1(Ref(0, 0, True, True)) == "$A$1"
